        (create_with("a b", json!({"Bogus": 1})), "QueueNameInvalid"),
        (create_with("a", json!({"ContentBasedDeduplication": true})), "InvalidParameterValue"),
        (create_with("a", json!({"DeadLetterQueue": "x"})), "InvalidParameterValue"),
        (create_with("a", json!({"DeadLetterQueue": "x", "MaxReceiveCount": 0})), "InvalidParameterValue"),
        (create_with("a", json!({"DeadLetterQueue": "x", "MaxReceiveCount": 2})), "QueueDoesNotExist"),
        (create_with("a", json!({"RetentionSeconds": 59})), "InvalidParameterValue"),
